func parseArgs(args []string) (Config, bool, bool) {
	cfg := Config{}
	// needHelp, needVersion
	needHelp := false
	needVersion := false
	remaining := []string{}
	for _, a := range args {
		switch a {
		case "--help", "-h":
			needHelp = true
		case "--version", "-v":
			needVersion = true
		case "--icons":
			cfg.Icons = true
		case "--dir-only":
			cfg.DirOnly = true
		case "--hide-hidden":
			cfg.HideHidden = true
		case "--preview":
			cfg.Preview = true
		case "--with-border":
			cfg.WithBorder = true
		case "--fuzzy":
			cfg.Fuzzy = true
		default:
			// if starts with -- and not known, treat as path? But then help/version flags already handled.
			// So any other --... is considered path (as observed)
			// Also single dash?
			remaining = append(remaining, a)
		}
	}
	if len(remaining) > 0 {
		cfg.Path = remaining[0]
		// extra args ignored (use first)
	}
	return cfg, needHelp, needVersion
}

// file entry
type entry struct {
	name  string
	isDir bool
	mode  fs.FileMode
}

func readDir(dir string, dirOnly bool, hideHidden bool) ([]entry, error) {
	f, err := os.Open(dir)
	if err != nil {
		return nil, err
	}
	defer f.Close()
infos, err := f.ReadDir(-1)
	if err != nil {
		return nil, err
	}
	var res []entry
	for _, de := range infos {
		name := de.Name()
		if hideHidden && strings.HasPrefix(name, ".") {
			continue
		}
		isDir := de.IsDir()
		if dirOnly && !isDir {
			// also need to handle symlinks to dirs? os.ReadDir returns IsDir true for symlink to dir? In Go, DirEntry.IsDir follows? Actually for symlink, IsDir returns false even if target is dir? Let's check: symlink to dir, IsDir false but mode is symlink. In walk, symlink to dir probably shown as dir? But we will treat symlink as file unless it is dir via stat?
			// For simplicity, we treat only true dirs.
			continue
		}
		// get mode via info
		info, err := de.Info()
		var mode fs.FileMode
		if err == nil {
			mode = info.Mode()
		}
		// For symlink, check if target is dir to allow navigation? In earlier symlink test, link_to_dir was shown as "link_to_dir" without trailing slash in non-icons, but with icons it showed as file? Actually in symlink test without icons: "link_to_dir" not "link_to_dir/" so not considered dir. So dirOnly should filter symlinks.
		res = append(res, entry{name: name, isDir: isDir, mode: mode})
	}
	sort.Slice(res, func(i, j int) bool {
		return res[i].name < res[j].name
	})
	return res, nil
}

// UI state
type UI struct {
	cfg        Config
	curDir     string
	entries    []entry
	cursor     int
	hideHidden bool
	dirOnly    bool
	icons      bool
	preview    bool
	withBorder bool
	fuzzy      bool
	fuzzyQuery string
	filtered   []entry
	showHelp   bool
	statusExpr string
	statusFn   func(string, []string, FileInfoProvider) string
	quitWithCD bool // true if q/esc, false if ctrl-c
	quit       bool
	// for yank message
	message    string
	messageTime time.Time
	// for delete undo (not implemented, but keep)
}

func (ui *UI) currentFiltered() []entry {
	if ui.fuzzy && ui.fuzzyQuery != "" {
		return ui.filtered
	}
	return ui.entries
}

func (ui *UI) selectedEntry() *entry {
	list := ui.currentFiltered()
	if len(list) == 0 {
		return nil
	}
	if ui.cursor < 0 {
		ui.cursor = 0
	}
	if ui.cursor >= len(list) {
		ui.cursor = len(list) - 1
	}
	return &list[ui.cursor]
}

func (ui *UI) updateFiltered() {
	if ui.fuzzyQuery == "" {
		ui.filtered = ui.entries
		return
	}
	q := strings.ToLower(ui.fuzzyQuery)
	var out []entry
	for _, e := range ui.entries {
		if strings.Contains(strings.ToLower(e.name), q) {
			// simple substring fuzzy (original uses fuzzy search maybe)
			out = append(out, e)
		} else {
			// also try fuzzy: check if characters in order
			if fuzzyMatch(q, strings.ToLower(e.name)) {
				out = append(out, e)
			}
		}
	}
	ui.filtered = out
	if ui.cursor >= len(ui.filtered) {
		ui.cursor = len(ui.filtered) - 1
	}
	if ui.cursor < 0 && len(ui.filtered) > 0 {
		ui.cursor = 0
	}
}

func fuzzyMatch(query, target string) bool {
	// simple: all chars of query appear in target in order
	qi := 0
	for _, c := range target {
		if qi < len(query) && byte(c) == query[qi] {
			qi++
		}
	}
	return qi == len(query)
}

func (ui *UI) reload() error {
	entries, err := readDir(ui.curDir, ui.dirOnly, ui.hideHidden)
	if err != nil {
		return err
	}
	ui.entries = entries
	ui.updateFiltered()
	// adjust cursor
	if len(ui.currentFiltered()) == 0 {
		ui.cursor = 0
	} else if ui.cursor >= len(ui.currentFiltered()) {
		ui.cursor = len(ui.currentFiltered()) - 1
	}
	return nil
}

