		sep := "  "
		if ui.withBorder {
			sep = " │ "
		}
		// Available width: cols, height rows
		// We'll render header: directory name and selected file name
		dirBase := filepath.Base(ui.curDir)
		if dirBase == "." || dirBase == "" {
			dirBase = ui.curDir
		}
		sel := ui.selectedEntry()
		selName := ""
		if sel != nil {
			selName = sel.name
			if sel.isDir {
				selName += "/"
			}
		}
		// header line
		header := fmt.Sprintf("%s%s%s", dirBase, sep, selName)
		fmt.Fprint(tty, "\r"+header+"\r\n")
		// list files left, preview right
		list := ui.currentFiltered()
		// preview content
		var previewLines []string
		if sel != nil {
			full := filepath.Join(ui.curDir, sel.name)
			if sel.isDir {
				// list dir contents
				ents, err := readDir(full, false, ui.hideHidden)
				if err == nil {
					for _, e := range ents {
						n := e.name
						if e.isDir {
							n += "/"
						}
						previewLines = append(previewLines, n)
					}
					if len(previewLines) == 0 {
						previewLines = []string{""}
					}
				}
			} else {
				// file preview: read first N lines
				b, err := os.ReadFile(full)
				if err == nil {
					// split lines
					s := string(b)
					// replace tabs?
					lines := strings.Split(s, "\n")
					for i, l := range lines {
						if i >= rows-2 {
							break
						}
						// truncate to preview width?
						if len(l) > cols/2 {
							l = l[:cols/2]
						}
						previewLines = append(previewLines, l)
					}
				}
			}
		}
		// render rows
		maxRows := rows - 2 // header and footer?
		if maxRows < 1 {
			maxRows = 1
		}
		for i := 0; i < maxRows; i++ {
			left := ""
			if i < len(list) {
				e := list[i]
				n := e.name
				if e.isDir {
					n += "/"
				}
				if ui.icons {
					icon := getIcon(e.name, e.isDir, e.mode, false)
					n = icon + " " + n
				}
				// highlight selected?
				if i == ui.cursor {
					// we can use reverse? But observed output not clearly highlight; we just print marker?
					// For simplicity, we will prefix with something? But original uses colors; we ignore.
				}
				left = n
			}
			right := ""
			if i < len(previewLines) {
				right = previewLines[i]
			}
			// pad left to col/2?
			// We'll just print left + sep + right
			leftWidth := cols/2 - len(sep)
			if leftWidth < 10 {
				leftWidth = 10
			}
			// pad/truncate left
			if len(left) > leftWidth {
				left = left[:leftWidth]
			} else {
				left = left + strings.Repeat(" ", leftWidth-len(left))
			}
			line := left + sep + right
			if len(line) > cols {
				line = line[:cols]
			}
			fmt.Fprint(tty, line+"\r\n")
		}
		// footer for status bar? In preview mode, status bar maybe not shown? But we can show at bottom?
		// Original preview mode also shows status? Not visible. We'll ignore.

		// Move cursor and mark
		fmt.Fprint(tty, "\x1b[3;H\x1b[H")
		return
	}

	// Normal mode
	fmt.Fprint(tty, "\x1b[?25l\x1b[?2004h\r\r\n")
	list := ui.currentFiltered()
	if len(list) == 0 {
		// check if error case: directory read error? We handle earlier via special render?
		// For empty, show "No files"
		// Original shows a box:
		// ╭──────────╮
		// │ No files │
		// ╰──────────╯
		fmt.Fprint(tty, "╭──────────╮\r\n│ No files │\r\n╰──────────╯\x1b[D\x1b[3A\r\n\r\n\r\n\r\n")
		// But also need to handle error display for non-existent path: original shows box with error message
		// That error is rendered when readDir fails. We should detect and show.
		// However in normal empty we just show No files.
	} else {
		// Show files, two columns? Original shows two columns? In our earlier captures, normal mode showed 2 columns? Actually we saw:
		// ".hidden\nadir/    " with two entries per line? For 2 files it showed on same line? Let's mimic simple one per line for now.
		// Observed: with 2 files ".hidden" and "adir/" it showed both on first line separated? Actually output was "\r\n.hidden  \r\nadir/    \x1b[D\x1b[2A" meaning two lines? Wait that output had .hidden on line1, adir/ on line2 but with extra spaces.
		// We'll render one per line.
		for _, e := range list {
			n := e.name
			if e.isDir {
				n += "/"
			}
			if ui.icons {
				icon := getIcon(e.name, e.isDir, e.mode, false)
				n = icon + " " + n
			}
			fmt.Fprint(tty, n+"\r\n")
		}
		// Add cursor movement escapes to mimic?
		// We need to add \x1b[D\x1b[2A etc to match? But not necessary for functionality.
		// We'll add simple cursor up moves
		fmt.Fprint(tty, "\x1b[D")
		if len(list) >= 2 {
			fmt.Fprint(tty, "\x1b[2A")
		} else if len(list) == 1 {
			fmt.Fprint(tty, "\x1b[A")
		}
	}

	// status bar: if configured, show on next line?
	if ui.statusFn != nil && len(list) > 0 {
		sel := ui.selectedEntry()
		if sel != nil {
			full := filepath.Join(ui.curDir, sel.name)
			// need provider
			provider := &realProvider{baseDir: ui.curDir}
