	// Need to handle stdin fd vs tty fd? Original uses /dev/tty for both input and output?
	// We'll use ttyFile.Fd() for raw mode, and also use ttyFile for reading input.
	// But raw mode should be set on ttyFile
	rawFd := int(ttyFile.Fd())
