	units:=[]string{"B","K","M","G","T"}
	f:=float64(b)
	i:=0
	for f>=1024 && i<len(units)-1 { f/=1024; i++ }
	if f<10 { return fmt.Sprintf("%.1f%s", f, units[i]) }
	return fmt.Sprintf("%.0f%s", f, units[i])
}
func ownerName(fi fs.FileInfo) string {
