	}
	if data==nil {
		filetypeIcons["di"]=""
		filetypeIcons["fi"]=""
		filetypeIcons["ex"]=""
		filetypeIcons["ln"]=""
		return
	}
	s:=bufio.NewScanner(strings.NewReader(string(data)))
	for s.Scan() {
		line:=strings.TrimSpace(s.Text())
		if line==""||strings.HasPrefix(line,"#") { continue }
		parts:=strings.Fields(line)
		if len(parts)<2 { continue }
		pat,icon:=parts[0],parts[1]
		if !strings.Contains(pat,"*") && !strings.Contains(pat,".") {
			filetypeIcons[pat]=icon
		} else {
			iconMap[pat]=icon
		}
	}
	if _,ok:=filetypeIcons["di"];!ok { filetypeIcons["di"]="" }
	if _,ok:=filetypeIcons["fi"];!ok { filetypeIcons["fi"]="" }
}
func getIcon(name string, isDir bool, mode fs.FileMode, isLink bool) string {
	lower:=strings.ToLower(name)
	for pat,icon:=range iconMap {
		if strings.HasPrefix(pat,"*.") {
			ext:=strings.ToLower(pat[1:])
			if strings.HasSuffix(lower, strings.ToLower(ext)) { return icon }
		} else if strings.HasPrefix(pat,"*") {
			suffix:=strings.ToLower(pat[1:])
			if strings.HasSuffix(lower, suffix) { return icon }
		} else {
			if lower==strings.ToLower(pat) { return icon }
		}
	}
	if isLink { if v,ok:=filetypeIcons["ln"];ok { return v } }
	if isDir { if v,ok:=filetypeIcons["di"];ok { return v }; return "" }
	if mode&0111!=0 { if v,ok:=filetypeIcons["ex"];ok { return v }; return "" }
	if v,ok:=filetypeIcons["fi"];ok { return v }
	return ""
