			var names []string
			for _,e:=range ui.entries { names=append(names, e.name) }
			status:=ui.statusFn(full, names, provider)
			if status!="" {
				fmt.Fprint(tty, "\r\n"+status+"\x1b[D\x1b[2A")
			}
		}
	}
	if ui.fuzzy {
		fmt.Fprint(tty, "/"+ui.fuzzyQuery+"\r\n\x1b[D\x1b[2A")
	}
	if ui.message!="" && time.Since(ui.messageTime)<2*time.Second {
		fmt.Fprint(tty, "\r\n"+ui.message+"\x1b[D\x1b[2A")
	}
}
func (ui *UI) handleKey(b []byte) {
	if len(b)==0 { return }
	if ui.showHelp {
		ui.showHelp=false
		if len(b)==1 && (b[0]=='q' || b[0]==27) { ui.boolQuit=true; ui.quitWithCD=true; return }
		if len(b)==1 && b[0]==3 { ui.boolQuit=true; ui.quitWithCD=false; return }
		return
	}
	if ui.fuzzy {
		if len(b)==1 {
			c:=b[0]
			if c==27 { ui.fuzzy=false; ui.fuzzyQuery=""; ui.updateFiltered(); return }
			if c==13||c==10 { ui.fuzzy=false; return }
			if c==127||c==8 {
				if len(ui.fuzzyQuery)>0 { ui.fuzzyQuery=ui.fuzzyQuery[:len(ui.fuzzyQuery)-1]; ui.updateFiltered() } else { ui.fuzzy=false }
				return
			}
			if c==3 { ui.boolQuit=true; ui.quitWithCD=false; return }
			if c>=32 && c<=126 { ui.fuzzyQuery+=string(c); ui.updateFiltered(); return }
		}
	}
	if len(b)==1 {
		c:=b[0]
		switch c {
		case 'q',27: ui.boolQuit=true; ui.quitWithCD=true; return
		case 3: ui.boolQuit=true; ui.quitWithCD=false; return
		case 'j':
			ui.cursor++; if ui.cursor>=len(ui.currentFiltered()) { ui.cursor=0 }; return
		case 'k':
			ui.cursor--; if ui.cursor<0 { ui.cursor=len(ui.currentFiltered())-1; if ui.cursor<0 { ui.cursor=0 } }; return
		case 'h': return
		case 'l':
			sel:=ui.selectedEntry(); if sel!=nil && sel.isDir { ui.curDir=filepath.Join(ui.curDir, sel.name); ui.cursor=0; ui.reload() }; return
		case ' ': ui.preview=!ui.preview; return
		case '.': ui.hideHidden=!ui.hideHidden; ui.reload(); return
		case '/': ui.fuzzy=true; ui.fuzzyQuery=""; ui.updateFiltered(); return
		case 'y':
			sel:=ui.selectedEntry(); if sel!=nil { full:=filepath.Join(ui.curDir, sel.name); ui.message="copied: "+full; ui.messageTime=time.Now(); tryCopy(full) }; return
		case 'd','u': return
		case '?': ui.showHelp=true; return
		case 127,8:
			parent:=filepath.Dir(ui.curDir); if parent!=ui.curDir { ui.curDir=parent; ui.cursor=0; ui.reload() }; return
		case 13:
			sel:=ui.selectedEntry(); if sel!=nil {
				if sel.isDir { ui.curDir=filepath.Join(ui.curDir, sel.name); ui.cursor=0; ui.reload() } else { openFile(filepath.Join(ui.curDir, sel.name)) }
			}; return
		}
	} else {
		if b[0]==27 && b[1]=='[' {
			seq:=string(b)
			switch seq {
			case "\x1b[A": ui.cursor--; if ui.cursor<0 { ui.cursor=len(ui.currentFiltered())-1; if ui.cursor<0 { ui.cursor=0 } }
			case "\x1b[B": ui.cursor++; if ui.cursor>=len(ui.currentFiltered()) { ui.cursor=0 }
			case "\x1b[C","\x1b[D","\x1b[3~": 
			case "\x1b[H","\x1b[1;2A","\x1b[1;2D": ui.cursor=0
			case "\x1b[F","\x1b[1;2B","\x1b[1;2C": ui.cursor=len(ui.currentFiltered())-1; if ui.cursor<0 { ui.cursor=0 }
			}
		} else if b[0]==27 && len(b)==1 { ui.boolQuit=true; ui.quitWithCD=true }
	}
}
func tryCopy(p string) {
	for _,c:=range [][]string{{"xclip","-selection","clipboard"},{"xsel","--clipboard","--input"},{"pbcopy"},{"wl-copy"}} {
		cmd:=exec.Command(c[0],c[1:]...); cmd.Stdin=strings.NewReader(p); _=cmd.Run()
	}
}
func openFile(path string) {
	ext:=strings.ToLower(strings.TrimPrefix(filepath.Ext(path),"."))
	openWith:=os.Getenv("WALK_OPEN_WITH")
	editor:=os.Getenv("WALK_EDITOR")
	if editor=="" { editor=os.Getenv("EDITOR") }
	if openWith!="" {
		parts:=strings.FieldsFunc(openWith, func(r rune) bool { return r==','||r==';' })
		for _,p:=range parts {
			p=strings.TrimSpace(p); if p=="" { continue }
			kv:=strings.SplitN(p,":",2); if len(kv)!=2 { continue }
			if strings.ToLower(strings.TrimSpace(kv[0]))==ext {
				fields:=strings.Fields(strings.TrimSpace(kv[1]))
				if len(fields)==0 { continue }
				cmd:=exec.Command(fields[0], append(fields[1:], path)...)
				cmd.Stdin=os.Stdin; cmd.Stdout=os.Stdout; cmd.Stderr=os.Stderr; _=cmd.Run(); return
			}
		}
	}
	if editor!="" {
		fields:=strings.Fields(editor)
		cmd:=exec.Command(fields[0], append(fields[1:], path)...)
		cmd.Stdin=os.Stdin; cmd.Stdout=os.Stdout; cmd.Stderr=os.Stderr; _=cmd.Run(); return
	}
	for _,prog:=range []string{"less","more","cat"} {
		if _,err:=exec.LookPath(prog);err==nil {
			cmd:=exec.Command(prog, path)
			cmd.Stdin=os.Stdin; cmd.Stdout=os.Stdout; cmd.Stderr=os.Stderr; _=cmd.Run(); return
		}
	}
	if b,err:=os.ReadFile(path);err==nil { os.Stdout.Write(b) }
}
func renderError(tty *os.File, err error, path string) {
	msg:=err.Error()
	width:=len(msg)+4
	if width<12 { width=12 }
	top:="╭"+strings.Repeat("─",width-2)+"╮"
	mid:="│ "+msg+" │"
	if len(mid)<width { mid="│ "+msg+strings.Repeat(" ",width-len(mid)-1)+"│" }
	bottom:="╰"+strings.Repeat("─",width-2)+"╯"
	fmt.Fprint(tty, "\x1b[?25l\x1b[?2004h\r\r\n"+top+"\r\n"+mid+"\r\n"+bottom+"\x1b[D\x1b[3A\r\n\r\n\r\n\r\n")
}
type realProvider struct { baseDir string }
func (r *realProvider) fullPath(n string) string { if filepath.IsAbs(n) { return n }; return filepath.Join(r.baseDir,n) }
func (r *realProvider) Size(n string) string { fi,err:=os.Stat(r.fullPath(n)); if err!=nil { return "?" }; return humanSize(fi.Size()) }
func (r *realProvider) Mode(n string) string { fi,err:=os.Stat(r.fullPath(n)); if err!=nil { return "??????????" }; return fi.Mode().String() }
func (r *realProvider) Owner(n string) string { fi,err:=os.Stat(r.fullPath(n)); if err!=nil { return "unknown unknown" }; return ownerName(fi) }
func (r *realProvider) ModTime(n string) string { fi,err:=os.Stat(r.fullPath(n)); if err!=nil { return "?" }; return fi.ModTime().Format("Jan 2 15:04") }

func evalStatusBar(exprStr, currentFile string, files []string, provider FileInfoProvider) string {
	exprStr=strings.TrimSpace(exprStr)
	if strings.Contains(exprStr, "| join") {
		start:=strings.Index(exprStr,"[")
		end:=strings.LastIndex(exprStr,"]")
		if start!=-1 && end!=-1 && end>start {
			inner:=exprStr[start+1:end]
			parts:=splitComma(inner)
			var elems []string
			for _,p:=range parts {
				p=strings.TrimSpace(p)
				if strings.Contains(p,"|") {
					pp:=strings.Split(p,"|")
					val:=evalSimple(strings.TrimSpace(pp[0]),currentFile,provider)
					for i:=1;i<len(pp);i++ { val=applyPipe(val, strings.TrimSpace(pp[i])) }
					elems=append(elems,val)
				} else { elems=append(elems, evalSimple(p,currentFile,provider)) }
			}
			joinStart:=strings.Index(exprStr,"join(")
			sep:=" "
			if joinStart!=-1 {
				q1:=strings.Index(exprStr[joinStart:], "\"")
				if q1!=-1 { rest:=exprStr[joinStart+q1+1:]; q2:=strings.Index(rest,"\""); if q2!=-1 { sep=rest[:q2] } } else {
					q1=strings.Index(exprStr[joinStart:], "'")
					if q1!=-1 { rest:=exprStr[joinStart+q1+1:]; q2:=strings.Index(rest,"'"); if q2!=-1 { sep=rest[:q2] } }
				}
			}
			return strings.Join(elems,sep)
		}
	}
	if strings.Contains(exprStr,"|") {
		parts:=strings.Split(exprStr,"|")
		val:=evalSimple(strings.TrimSpace(parts[0]),currentFile,provider)
		for i:=1;i<len(parts);i++ { val=applyPipe(val, strings.TrimSpace(parts[i])) }
		return val
	}
	return evalSimple(exprStr,currentFile,provider)
}
func splitComma(s string) []string {
	var res []string; depth:=0; start:=0
	for i,c:=range s { if c=='(' {depth++} else if c==')' {depth--} else if c==',' && depth==0 { res=append(res,s[start:i]); start=i+1 } }
	res=append(res,s[start:])
	return res
}
func applyPipe(val,fnCall string) string {
	fnCall=strings.TrimSpace(fnCall)
	if strings.HasPrefix(fnCall,"PadLeft") {
		inner:=""; if idx:=strings.Index(fnCall,"("); idx!=-1 { inner=fnCall[idx+1:len(fnCall)-1] }
		inner=strings.TrimSpace(inner); var n int
		if strings.Contains(inner,",") { p:=strings.Split(inner,","); fmt.Sscanf(strings.TrimSpace(p[len(p)-1]),"%d",&n) } else { fmt.Sscanf(inner,"%d",&n) }
		if n<=0 { n=len(val) }
		if len(val)>=n { return val }
		return strings.Repeat(" ", n-len(val))+val
	}
	if strings.HasPrefix(fnCall,"PadRight") {
		inner:=""; if idx:=strings.Index(fnCall,"("); idx!=-1 { inner=fnCall[idx+1:len(fnCall)-1] }
		inner=strings.TrimSpace(inner); var n int
		if strings.Contains(inner,",") { p:=strings.Split(inner,","); fmt.Sscanf(strings.TrimSpace(p[len(p)-1]),"%d",&n) } else { fmt.Sscanf(inner,"%d",&n) }
		if n<=0 { n=len(val) }
		if len(val)>=n { return val }
		return val+strings.Repeat(" ", n-len(val))
	}
	return val
}
func evalSimple(expr, currentFile string, provider FileInfoProvider) string {
	expr=strings.TrimSpace(expr)
	if strings.HasPrefix(expr,"Sprintf") {
		start:=strings.Index(expr,"("); end:=strings.LastIndex(expr,")")
		if start!=-1 && end!=-1 {
			inner:=expr[start+1:end]
			parts:=splitArgs(inner)
			if len(parts)==0 { return "" }
			format:=unquote(strings.TrimSpace(parts[0]))
			var args []interface{}
			for _,p:=range parts[1:] {
				p=strings.TrimSpace(p)
				if p=="current_file.Name()" { args=append(args, filepath.Base(currentFile)) } else if strings.HasPrefix(p,"\"")||strings.HasPrefix(p,"'") { args=append(args, unquote(p)) } else if strings.HasPrefix(p,"current_file") { args=append(args, currentFile) } else {
					var i int
					if _,err:=fmt.Sscanf(p,"%d",&i);err==nil { args=append(args,i) } else { args=append(args,p) }
				}
			}
			if len(args)==0 { return format }
			return fmt.Sprintf(format, args...)
		}
	}
	if expr=="Size()" { return provider.Size(currentFile) }
	if expr=="Mode()" { return provider.Mode(currentFile) }
	if expr=="Owner()" { return provider.Owner(currentFile) }
	if expr=="ModTime()" { return provider.ModTime(currentFile) }
	if expr=="current_file.Name()" { return filepath.Base(currentFile) }
	if expr=="current_file" { return currentFile }
	if strings.HasPrefix(expr,"PadLeft")||strings.HasPrefix(expr,"PadRight") {
		start:=strings.Index(expr,"("); end:=strings.LastIndex(expr,")")
		if start!=-1 && end!=-1 {
			inner:=expr[start+1:end]
			parts:=splitArgs(inner)
			if len(parts)>=2 {
				s:=unquote(strings.TrimSpace(parts[0])); var n int; fmt.Sscanf(strings.TrimSpace(parts[1]),"%d",&n)
				if strings.HasPrefix(expr,"PadLeft") { if len(s)>=n { return s }; return strings.Repeat(" ", n-len(s))+s } else { if len(s)>=n { return s }; return s+strings.Repeat(" ", n-len(s)) }
			} else if len(parts)==1 { return unquote(strings.TrimSpace(parts[0])) }
		}
	}
	if strings.HasPrefix(expr,"files[") { return "" }
	if (strings.HasPrefix(expr,"\"") && strings.HasSuffix(expr,"\"")) || (strings.HasPrefix(expr,"'") && strings.HasSuffix(expr,"'")) { return unquote(expr) }
	return expr
}
func splitArgs(s string) []string {
	var res []string; depth:=0; inS,inD:=false,false; start:=0
	for i,c:=range s {
		if c=='\'' && !inD { inS=!inS } else if c=='"' && !inS { inD=!inD }
		if inS||inD { continue }
		if c=='(' { depth++ } else if c==')' { depth-- } else if c==',' && depth==0 { res=append(res,s[start:i]); start=i+1 }
	}
	res=append(res,s[start:])
	return res
}
func unquote(s string) string {
	s=strings.TrimSpace(s)
	if len(s)>=2 && ((s[0]=='"'&&s[len(s)-1]=='"')||(s[0]=='\''&&s[len(s)-1]=='\'')) { return s[1:len(s)-1] }
	return s
}
func main() {
	cfg,needHelp,needVersion:=parseArgs(os.Args[1:])
	if needHelp { fmt.Fprint(os.Stderr, helpText); os.Exit(1) }
	if needVersion { fmt.Fprintln(os.Stdout, version); os.Exit(0) }
	statusExpr:=os.Getenv("WALK_STATUS_BAR")
	var statusFn func(string, []string, FileInfoProvider) string
	if statusExpr!="" { statusFn=compile(statusExpr) }
	if _,exists:=os.LookupEnv("WALK_STATUS_BAR"); exists && statusExpr=="" { statusFn=compile(statusExpr) }
	var ttyFile *os.File
	var ttyErr error
	ttyFile, ttyErr = os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if ttyErr!=nil {
		if isTerminal(int(os.Stdin.Fd())) { ttyFile=os.Stdin; ttyErr=nil } else if isTerminal(int(os.Stdout.Fd())) { ttyFile=os.Stdout; ttyErr=nil } else { panic("could not open a new TTY: open /dev/tty: no such device or address") }
	}
	_ = ttyErr
	if ttyFile!=os.Stdin && ttyFile!=os.Stdout { defer ttyFile.Close() }
	if cfg.Icons { initIcons() }
	initPath:=cfg.Path
	if initPath=="" { wd,_:=os.Getwd(); initPath=wd } else {
		if !filepath.IsAbs(initPath) { wd,_:=os.Getwd(); initPath=filepath.Join(wd,initPath) }
		initPath=filepath.Clean(initPath)
	}
	fi,errStat:=os.Stat(initPath)
	curDir:=initPath
	if fi!=nil && !fi.IsDir() { /* keep for error */ } else { curDir=initPath }
	ui:=&UI{cfg:cfg, curDir:curDir, hideHidden:cfg.HideHidden, dirOnly:cfg.DirOnly, icons:cfg.Icons, preview:cfg.Preview, withBorder:cfg.WithBorder, fuzzy:cfg.Fuzzy, statusFn:statusFn, cursor:0, quitWithCD:true}
	if fi!=nil && !fi.IsDir() { errStat=fmt.Errorf("readdirent %s: not a directory", initPath) }
	// initial reload
	initErr:=ui.reload()
	if errStat!=nil { initErr=errStat }
	// also handle non-existent
	if _,err:=os.Stat(curDir); err!=nil && errStat==nil { initErr=err }
	rawFd:=int(ttyFile.Fd())
	oldState,err:=makeRaw(rawFd)
	if err!=nil { panic(err) }
	defer restore(rawFd, oldState)
	rows,cols:=getWinSize(rawFd)
	if initErr!=nil { renderError(ttyFile, initErr, curDir) } else { ui.render(ttyFile, rows, cols) }
	buf:=make([]byte,64)
	for !ui.boolQuit {
		n,readErr:=ttyFile.Read(buf)
		if readErr!=nil { if readErr==io.EOF { break }; continue }
		if n==0 { continue }
		data:=make([]byte,n); copy(data,buf[:n])
		ui.handleKey(data)
		if ui.boolQuit { break }
		if err:=ui.reload(); err!=nil { renderError(ttyFile, err, ui.curDir) } else { rows,cols=getWinSize(rawFd); ui.render(ttyFile, rows, cols) }
	}
	fmt.Fprint(ttyFile, "\x1b[?2004l\x1b[?25h\x1b[?1002l\x1b[?1003l\x1b[?1006l")
	if ui.preview { fmt.Fprint(ttyFile, "\x1b[?1049l\x1b[?25h") }
	if ui.quitWithCD { fmt.Fprintln(os.Stdout, ui.curDir); os.Exit(0) } else { os.Exit(2) }
}
